}

#[test]
fn identifier_on_global_object_undefined() {
    run_test_actions([TestAction::assert_native_error(
        "bar;",
        JsNativeErrorKind::Reference,
        "bar is not defined",
    )]);
}

#[test]
fn object_field_set() {
    run_test_actions([TestAction::assert_eq(
        indoc! {r#"
            let m = {};
            m['key'] = 22;
            m['key']
        "#},
        22,
    )]);
}

#[test]
fn array_field_set() {
    run_test_actions([
        TestAction::run("let m;"),
        // element_changes
        TestAction::assert_eq(
            indoc! {r#"
                m = [1, 2, 3];
                m[1] = 5;
                m[1]
            "#},
            5,
        ),
        // length changes
        TestAction::assert_eq(
            indoc! {r#"
                m = [1, 2, 3];
                m[10] = 52;
                m.length
            "#},
            11,
        ),
        // negative_index_wont_affect_length
        TestAction::assert_eq(
            indoc! {r#"
                m = [1, 2, 3];
                m[-11] = 5;
                m.length
            "#},
            3,
        ),
        // non_num_key_wont_affect_length
        TestAction::assert_eq(
            indoc! {r#"
                m = [1, 2, 3];
                m["magic"] = 5;
                m.length
            "#},
            3,
        ),
    ]);
}

