            indoc! {r#"
                {
                    x = hello();

                    function hello() { return 5 }
                    var x;
                    x;
                }
            "#},
            5,
        ),
        TestAction::assert_eq(
            indoc! {r#"
                {
                    hello = function() { return 5 }
                    x = hello();

                    x;
                }
            "#},
            5,
        ),
        TestAction::assert_eq(
            indoc! {r#"
                {
                    let x = b();

                    function a() {return 5}
                    function b() {return a()}

                    x;
                }
            "#},
            5,
        ),
        TestAction::assert_eq(
            indoc! {r#"
                {
                    let x = b();

                    function b() {return a()}
                    function a() {return 5}

                    x;
                }
            "#},
            5,
        ),
    ]);
}

